// SPDX-License-Identifier: MIT
// Breadboard classic ESP32 template. Wire an external LED to GPIO2 and ground.
// Replace or add main/ sources; app_main() is the entry point.
#include <stdio.h>
#include "driver/gpio.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"

void app_main(void)
{
    gpio_reset_pin(GPIO_NUM_2);
    gpio_set_direction(GPIO_NUM_2, GPIO_MODE_OUTPUT);
    printf("Breadboard classic ESP32 template: hello from ESP-IDF\n");
    unsigned tick = 0;
    for (;;) {
        gpio_set_level(GPIO_NUM_2, tick & 1);
        printf("ESP32 template tick %u: LED %s\n", tick, (tick & 1) ? "on" : "off");
        ++tick;
        vTaskDelay(pdMS_TO_TICKS(500));
    }
}
